import os
import re
import json
import urllib.request
from google.protobuf import json_format

# Import compiled Protobuf bindings generated by protoc
import repo_pb2

CONFIG_FILE = "config.json"

def load_config():
    if not os.path.exists(CONFIG_FILE):
        raise FileNotFoundError(f"Configuration file '{CONFIG_FILE}' not found.")
    with open(CONFIG_FILE, "r", encoding="utf-8") as f:
        return json.load(f)

def find_matching_keywords(ext: dict, compiled_patterns: list) -> list[str]:
    matches = []
    name = ext.get("name", "")
    pkg = ext.get("pkg", "")
    sources = ext.get("sources", [])

    for raw_kw, pattern in compiled_patterns:
        if pattern.search(name):
            matches.append(f"'{raw_kw}' in name ('{name}')")
            continue
        if pattern.search(pkg):
            matches.append(f"'{raw_kw}' in pkg ('{pkg}')")
            continue
        for src in sources:
            src_name = src.get("name", "")
            if pattern.search(src_name):
                matches.append(f"'{raw_kw}' in source ('{src_name}')")
                break
    return matches

def write_repo_files(items: list[dict], target_dir: str, repo_title: str, signing_key: str):
    os.makedirs(target_dir, exist_ok=True)

    # 1. Output index.min.json
    json_path = os.path.join(target_dir, "index.min.json")
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(items, f, separators=(',', ':'))

    # 2. Output index.pb
    ext_list = repo_pb2.ExtensionList()
    for item in items:
        ext_msg = ext_list.extensions.add()
        if "sources" in item:
            for s in item["sources"]:
                if "id" in s:
                    s["id"] = str(s["id"])
        json_format.ParseDict(item, ext_msg, ignore_unknown_fields=True)

    pb_path = os.path.join(target_dir, "index.pb")
    with open(pb_path, "wb") as f:
        f.write(ext_list.SerializeToString())

    # 3. Output repo.json descriptor
    repo_meta = {
        "meta": {
            "name": repo_title,
            "website": "https://keiyoushi.github.io",
            "signingKeyFingerprint": signing_key
        }
    }
    with open(os.path.join(target_dir, "repo.json"), "w", encoding="utf-8") as f:
        json.dump(repo_meta, f, indent=2)

def fetch_and_split():
    config = load_config()
    upstream_url = config.get("upstream_index_url")
    signing_key = config.get("signing_key_fingerprint", "")
    sfw_title = config.get("repos", {}).get("sfw", {}).get("name", "Keiyoushi fork sfw")
    nsfw_title = config.get("repos", {}).get("nsfw", {}).get("name", "Keiyoushi fork 18+")
    
    whitelist_set = set(config.get("whitelist_pkg", []))
    compiled_patterns = [
        (kw, re.compile(kw, re.IGNORECASE)) 
        for kw in config.get("nsfw_keywords", [])
    ]

    print(f"Fetching upstream index from: {upstream_url}")
    req = urllib.request.Request(upstream_url, headers={'User-Agent': 'Mozilla/5.0'})
    with urllib.request.urlopen(req) as resp:
        extensions = json.loads(resp.read().decode('utf-8'))

    sfw_items = []
    nsfw_items = []
    
    keyword_caught_count = 0
    whitelist_count = 0

    print("\n" + "=" * 80)
    print("EXTENSION ROUTING AUDIT LOG")
    print("=" * 80)

    for ext in extensions:
        name = ext.get("name", "Unknown")
        pkg = ext.get("pkg", "Unknown")

        # 1. Whitelist Check
        if pkg in whitelist_set:
            whitelist_count += 1
            ext["nsfw"] = 0
            sfw_items.append(ext)
            print(f"[WHITELIST OVERRIDE] {name} ({pkg}) forced to SFW.")
            continue

        # 2. Flag and Keyword Checks
        is_official_nsfw = bool(ext.get("nsfw", 0) or ext.get("isNsfw", 0))
        matches = find_matching_keywords(ext, compiled_patterns)

        if matches and not is_official_nsfw:
            keyword_caught_count += 1
            print(f"[UNTAGGED -> CAUGHT] {name} ({pkg})")
            print(f"  └─ Reasons: {', '.join(matches)}\n")

        # 3. Assign
        if is_official_nsfw or matches:
            ext["nsfw"] = 1
            nsfw_items.append(ext)
        else:
            sfw_items.append(ext)

    print("=" * 80)
    print("Audit Summary:")
    print(f"  - Total Evaluated            : {len(extensions)}")
    print(f"  - SFW Extensions Filtered    : {len(sfw_items)}")
    print(f"  - NSFW Extensions Filtered   : {len(nsfw_items)}")
    print(f"  - Untagged Caught by Keywords: {keyword_caught_count}")
    print(f"  - Whitelist Overrides        : {whitelist_count}")
    print("=" * 80 + "\n")

    write_repo_files(sfw_items, "dist/sfw", sfw_title, signing_key)
    write_repo_files(nsfw_items, "dist/nsfw", nsfw_title, signing_key)
    print("Files successfully generated in dist/sfw and dist/nsfw.")

if __name__ == "__main__":
    fetch_and_split()
